from sqlalchemy import *
from sqlalchemy.types import Uuid
metadata=MetaData()
definitions=Table("feature_definitions",metadata,Column("definition_id",Uuid,primary_key=True),Column("name",String,nullable=False,unique=True),Column("purpose",String,nullable=False),Column("formula",String,nullable=False),Column("economic_meaning",String,nullable=False),Column("direction",Integer,nullable=False),Column("frequency",String,nullable=False),Column("owner",String,nullable=False),CheckConstraint("direction IN (-1,1)"))
versions=Table("feature_versions",metadata,Column("version_id",Uuid,primary_key=True),Column("definition_id",Uuid,ForeignKey("feature_definitions.definition_id"),nullable=False),Column("version",String,nullable=False),Column("code_version",String,nullable=False),Column("parameters",JSON,nullable=False),Column("dependency_versions",JSON,nullable=False),Column("min_history",Integer,nullable=False),Column("missing_policy",String,nullable=False),Column("transform",String,nullable=False),Column("active",Boolean,nullable=False),UniqueConstraint("definition_id","version"),CheckConstraint("min_history>0"))
bindings=Table("feature_purpose_bindings",metadata,Column("purpose",String,primary_key=True),Column("version_ids",JSON,nullable=False))
sets=Table("feature_sets",metadata,Column("feature_set_id",Uuid,primary_key=True),Column("purpose",String,nullable=False),Column("as_of_date",Date,nullable=False),Column("decision_at",DateTime(timezone=True),nullable=False),Column("universe_snapshot_id",Uuid,nullable=False),Column("data_snapshot_id",Uuid,nullable=False),Column("version_ids",JSON,nullable=False),Column("member_ids",JSON,nullable=False),Column("input_hash",String,nullable=False,unique=True),Column("content_hash",String,nullable=False),Column("factor_version",String))
feature_values_table=Table("feature_values",metadata,Column("value_id",Uuid,primary_key=True),Column("feature_set_id",Uuid,ForeignKey("feature_sets.feature_set_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("as_of_date",Date,nullable=False),Column("version_id",Uuid,ForeignKey("feature_versions.version_id"),nullable=False),Column("data_snapshot_id",Uuid,nullable=False),Column("value",Numeric),Column("quality",String,nullable=False),Column("input_refs",JSON,nullable=False),Column("steps",JSON,nullable=False),UniqueConstraint("instrument_id","as_of_date","version_id","data_snapshot_id"))
events=Table("feature_events",metadata,Column("event_id",Uuid,primary_key=True),Column("event_type",String,nullable=False),Column("feature_set_id",Uuid,nullable=False),Column("occurred_at",DateTime(timezone=True),nullable=False),Column("reasons",JSON,nullable=False))
diagnostics=Table("feature_diagnostics",metadata,Column("diagnostic_id",Uuid,primary_key=True),Column("version_id",Uuid,nullable=False),Column("as_of_date",Date,nullable=False),Column("metric",String,nullable=False),Column("value",Numeric,nullable=False),Column("research_only",Boolean,nullable=False),CheckConstraint("research_only"))
